head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[autoComplete > P > accessibility]<br/>AutoComplete 컴포넌트에 웹접근성 지원 기능을 일괄적으로 적용할지 설정합니다.",
    "validation" : [
        "true 설정 시, renderType 속성값에 관계없이 입력창이 항상 표시되는 구조로 렌더링되며 선택된 아이템이 입력창에 표시됩니다.",
        "true 설정 시, 컴포넌트의 최상위 요소에 'w2autoComplete' 클래스 대신 'w2autoComplete_acc' 클래스가 설정됩니다.",
        "true 설정 시, 화살표 버튼이 'button' 요소로 렌더링되며 tabindex='-1' 이 설정되어 Tab 키에 의한 포커스 이동에서 제외됩니다.",
        "true 설정 시, 아이템 리스트창이 'ul', 'li' 요소로 렌더링되며 'ul' 요소에 role='listbox', 'li' 요소에 role='option' 속성이 추가됩니다.",
        "true 설정 시, 아이템 리스트창이 닫힌 상태에서 입력창에 아래 화살표키를 입력하면 전체 아이템이 표시된 아이템 리스트창이 열립니다.",
        "true 설정 시, 모바일 환경에서는 아이템 리스트창이 컴포넌트 내부에 렌더링되며 컴포넌트의 최상위 요소에 tabIndex 속성이 설정되지 않습니다.",
        "false 설정 시, AutoComplete 컴포넌트에 웹접근성 지원 기능을 적용하지 않습니다.",
        "미설정 시, AutoComplete 컴포넌트에 웹접근성 지원 기능을 적용하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // con_accessibility 기본값 true
    con_accessibility.setValue("2");

    // 리스트창 확인 버튼 클릭 시 목록이 먼저 닫히므로 mousedown capture 단계에서 열림 상태를 기록
    btn_getItemTableInfo.render.addEventListener("mousedown", scwin.captureItemTableState, true);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[절차]\n1. 화살표 버튼으로 목록을 열어 아이템 선택 -> 렌더링 구조 확인\n2. 입력창 클릭 -> 아래 화살표키 -> 목록이 열린 상태에서 리스트창 확인"', '', 'label1');

    let properties = {
        accessibility : con_accessibility.getText(),
        renderType : con_renderType.getValue(),
    }

    let cList = $c.gcm.createCList(properties);

    $c.gcm.createBasicAutoComplete(cList);
}



// 컴포넌트 최상위 요소, 입력창, 화살표 버튼 구조 출력 (validation 1, 2, 3, 6(tabIndex), 7, 8)
scwin.btn_getRenderInfo_onclick = function (e) {
    let render = target1.render;
    let compClass = render.className.split(" ").filter(function (c) { return c === "w2autoComplete" || c === "w2autoComplete_acc"; }).join(" ");
    let tabIndexAttr = render.hasAttribute("tabIndex") ? render.getAttribute("tabIndex") : "없음";
    wf_body_bottom.getObj("scwin").setReturnValue("최상위 요소 class : " + compClass + " / tabIndex : " + tabIndexAttr);

    let inputElem = document.querySelector("input[id='" + target1.id + "_input']");
    let inputShown = !!inputElem && getComputedStyle(inputElem).display !== "none";
    let inputInfo = "입력창 표시 : " + inputShown + (inputShown ? " / 입력창 값 : " + inputElem.value : "");
    wf_body_bottom.getObj("scwin").setReturnValue(inputInfo);

    let arrowElem = document.querySelector("[id='" + target1.id + "_arrow'], [id='" + target1.id + "_button']");
    if (arrowElem) {
        let arrowTabIndex = arrowElem.hasAttribute("tabindex") ? arrowElem.getAttribute("tabindex") : "없음";
        wf_body_bottom.getObj("scwin").setReturnValue("화살표 버튼 : " + arrowElem.tagName + " (tabindex : " + arrowTabIndex + ")");
    }
};



// 버튼 mousedown 시점(목록이 닫히기 전)의 리스트창 열림 상태·표시 아이템 수 기록
scwin.captureItemTableState = function (e) {
    let itemTableElem = document.querySelector("[id='" + target1.id + "_itemTable']");
    scwin.itemTableState = null;
    if (!itemTableElem) {
        return;
    }
    let isOpen = getComputedStyle(itemTableElem).display !== "none" && getComputedStyle(itemTableElem).visibility !== "hidden";
    let itemElems = itemTableElem.querySelectorAll("li, tr");
    let shownCount = Array.prototype.filter.call(itemElems, function (item) { return item.offsetParent !== null; }).length;
    scwin.itemTableState = { isOpen : isOpen, shownCount : shownCount };
};



// 아이템 리스트창 구조/위치/표시 아이템 수 출력 (validation 4, 5, 6(위치), 7, 8)
scwin.btn_getItemTableInfo_onclick = function (e) {
    let itemTableElem = document.querySelector("[id='" + target1.id + "_itemTable']");
    if (!itemTableElem) {
        wf_body_bottom.getObj("scwin").setReturnValue("아이템 리스트창 생성 : false");
        return;
    }

    let listElem = itemTableElem.querySelector("ul, table");
    let itemElems = listElem ? listElem.querySelectorAll(listElem.tagName === "UL" ? "li" : "tr") : [];
    let itemElem = itemElems.length > 0 ? itemElems[0] : null;
    wf_body_bottom.getObj("scwin").setReturnValue("리스트창 : " + (listElem ? listElem.tagName : "") + " (role : " + (listElem ? listElem.getAttribute("role") : "") + ") / 아이템 : " + (itemElem ? itemElem.tagName : "") + " (role : " + (itemElem ? itemElem.getAttribute("role") : "") + ")");

    let position = target1.render.contains(itemTableElem) ? "컴포넌트 내부" : itemTableElem.parentNode.tagName;
    let state = scwin.itemTableState || { isOpen : false, shownCount : 0 };
    wf_body_bottom.getObj("scwin").setReturnValue("리스트창 위치 : " + position + " / 열림 : " + state.isOpen + " / 표시 아이템 수 : " + state.shownCount + " (전체 " + gdl_autocomplete.getRowCount() + ")");
};
